import{_ as t,o,c as i,ag as a}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Polish checklist","description":"","frontmatter":{"source":"weeks/15-ship-it/polish-checklist.md"},"headers":[],"relativePath":"weeks/15-ship-it/polish-checklist.md","filePath":"weeks/15-ship-it/polish-checklist.md"}'),n={name:"weeks/15-ship-it/polish-checklist.md"};function s(r,e,l,h,c,d){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="polish-checklist" tabindex="-1">Polish checklist <a class="header-anchor" href="#polish-checklist" aria-label="Permalink to &quot;Polish checklist&quot;">​</a></h1><blockquote><p>A practical, tickable list for the week 15 polish sprint (both studios) and homework. Work top to bottom; each item is small. For every fix: write the &quot;done when&quot; check, make one change, test it, read the diff, teach back, commit (<a href="./../../resources/safe-loop.html">Safe Loop</a>). Not every item applies to every app. Skip what genuinely doesn&#39;t, but say why.</p></blockquote><h2 id="how-to-use-it" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to &quot;How to use it&quot;">​</a></h2><p>Go through your <strong>live</strong> site (the production URL), not just localhost. Test on a phone-sized window (your browser&#39;s device toolbar, or your actual phone). Fix the quick wins first. Sections 1–4 matter most; whatever you don&#39;t finish in the studio is homework.</p><hr><h2 id="1-the-three-states-empty-loading-error" tabindex="-1">1. The three states: empty, loading, error <a class="header-anchor" href="#1-the-three-states-empty-loading-error" aria-label="Permalink to &quot;1. The three states: empty, loading, error&quot;">​</a></h2><ul><li>☐ <strong>Empty state.</strong> Open the app with no data (new user, empty list). Does it show something helpful (&quot;No notes yet — add one above&quot;), not a blank screen or a broken layout? (In JavaScript, test <code>items.length === 0</code>: unlike in Python, an empty array is truthy.)</li><li>☐ <strong>Loading state.</strong> For anything that waits (an API call, a database read), is there a spinner, a &quot;Loading…&quot; line, or a disabled button, so the app doesn&#39;t look frozen?</li><li>☐ <strong>Error state.</strong> Force a failure (turn off wifi, submit bad input). Does the app show a friendly message that says what to do next, instead of freezing or doing nothing?</li></ul><p>✅ <strong>Checkpoint:</strong> you triggered all three states on purpose and each looks intentional.</p><h2 id="2-works-on-a-phone" tabindex="-1">2. Works on a phone <a class="header-anchor" href="#2-works-on-a-phone" aria-label="Permalink to &quot;2. Works on a phone&quot;">​</a></h2><ul><li>☐ There&#39;s a viewport tag: <code>&lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1&quot;&gt;</code>.</li><li>☐ Nothing overflows sideways; no horizontal scrollbar at phone width.</li><li>☐ Buttons and links are big enough to tap (roughly 44px).</li><li>☐ Text is readable without zooming.</li></ul><h2 id="3-identity-title-favicon-headings" tabindex="-1">3. Identity: title, favicon, headings <a class="header-anchor" href="#3-identity-title-favicon-headings" aria-label="Permalink to &quot;3. Identity: title, favicon, headings&quot;">​</a></h2><ul><li>☐ The browser tab shows a real <strong><code>&lt;title&gt;</code></strong>, not &quot;Untitled&quot; or &quot;Document&quot;.</li><li>☐ There&#39;s a <strong>favicon</strong> (even a simple SVG or a small PNG) so the tab isn&#39;t blank.</li><li>☐ There is exactly one main <strong><code>&lt;h1&gt;</code></strong>, and headings go in order (don&#39;t skip levels for styling).</li></ul><h2 id="4-accessibility-basics" tabindex="-1">4. Accessibility basics <a class="header-anchor" href="#4-accessibility-basics" aria-label="Permalink to &quot;4. Accessibility basics&quot;">​</a></h2><ul><li>☐ Every meaningful <strong>image has <code>alt</code> text</strong>. Purely decorative images have <code>alt=&quot;&quot;</code>.</li><li>☐ Every input has a <strong><code>&lt;label&gt;</code></strong> (or an <code>aria-label</code>), so it&#39;s clear what to type.</li><li>☐ <strong>Color contrast</strong> is strong enough to read (dark text on light, or the reverse). If unsure, run your browser&#39;s accessibility panel or Lighthouse audit.</li><li>☐ You can use the whole app with the <strong>keyboard only</strong> (Tab to move, Enter/Space to activate).</li><li>☐ The element you&#39;re on shows a <strong>visible focus outline</strong> (don&#39;t remove it in CSS without a replacement).</li><li>☐ Nothing important is signaled by <strong>color alone</strong> (add text or an icon too).</li></ul><p>✅ <strong>Checkpoint:</strong> you tabbed through the entire app with no mouse and could see and use everything.</p><p>Using a screen reader or keyboard yourself? The <a href="./../../resources/accessibility.html">Accessibility guide</a> covers the course&#39;s tools.</p><h2 id="5-content-and-copy" tabindex="-1">5. Content and copy <a class="header-anchor" href="#5-content-and-copy" aria-label="Permalink to &quot;5. Content and copy&quot;">​</a></h2><ul><li>☐ No leftover placeholder text (&quot;Lorem ipsum&quot;, &quot;TODO&quot;, &quot;rest of code here&quot;).</li><li>☐ Buttons say what they do (&quot;Save note&quot;, not &quot;Submit&quot;).</li><li>☐ Numbers and dates are formatted for a human, not raw.</li><li>☐ Spelling checked (your editor or a quick read-through).</li></ul><h2 id="6-readme-a-stranger-can-follow" tabindex="-1">6. README a stranger can follow <a class="header-anchor" href="#6-readme-a-stranger-can-follow" aria-label="Permalink to &quot;6. README a stranger can follow&quot;">​</a></h2><p>Use the <a href="./../../templates/PROJECT_README.html">README template</a>. Confirm it has:</p><ul><li>☐ One sentence saying what it does and who it&#39;s for.</li><li>☐ The <strong>production URL</strong>.</li><li>☐ A screenshot.</li><li>☐ How to run it locally (<code>npm install</code>, <code>.env</code> from <code>.env.example</code>, <code>public/config.js</code> from <code>public/config.example.js</code> if you use Supabase, <code>npm run dev</code>).</li><li>☐ A short &quot;how it works&quot; (which files matter, where data goes, where each key lives and why).</li><li>☐ The one-line <strong>&quot;Authorization is enforced in: …&quot;</strong> answer.</li><li>☐ An honest <strong>Known issues</strong> section: what doesn&#39;t work, when, any workaround, and what you&#39;d do next. Naming a real limitation never costs points.</li><li>☐ A short <strong>Next steps</strong> section: what you&#39;d build or fix next.</li><li>☐ Credits for any code, images, fonts or APIs you reused.</li></ul><p>✅ <strong>Checkpoint:</strong> someone else could get your app running from the README alone (your week 14 handoff test said so, or you fixed what it found).</p><h2 id="7-final-technical-pass" tabindex="-1">7. Final technical pass <a class="header-anchor" href="#7-final-technical-pass" aria-label="Permalink to &quot;7. Final technical pass&quot;">​</a></h2><ul><li>☐ <code>npm test</code> passes.</li><li>☐ <code>npm run check:secrets</code> finds nothing (it checks your git history too).</li><li>☐ The production URL actually works in a fresh browser (try a private window).</li><li>☐ If you use a database: RLS is on, and the grants match your &quot;who may do what&quot; table.</li><li>☐ Your <code>SECURITY_CHECKLIST.md</code> is complete (do the <a href="./lab.html#part-b2--final-security-pass-core-15-min">final security pass</a>).</li><li>☐ The browser console shows no red errors on the live site.</li></ul><h2 id="8-the-little-things-optional-but-nice" tabindex="-1">8. The little things (optional but nice) <a class="header-anchor" href="#8-the-little-things-optional-but-nice" aria-label="Permalink to &quot;8. The little things (optional but nice)&quot;">​</a></h2><ul><li>☐ A short, clear app name and one-line tagline on the page.</li><li>☐ Consistent spacing and alignment.</li><li>☐ A &quot;reduced motion&quot; fallback if you use animation.</li><li>☐ A visible link back to your repo (open source is honest).</li></ul><hr><p>When you can tick sections 1–7, your capstone is <strong>shippable</strong>. Commit, then rehearse your five-minute presentation (<a href="./lab.html#part-b3--rehearse-your-final-presentation-core-20-min">lab Part B3</a>).</p>',28)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
